import{_ as a,o as r,c as t,ao as i}from"./chunks/framework.Ce3MqT8w.js";const o="/ImplicitGlobalGrid.jl/previews/PR131/assets/fig_parEff_HM3D_Julia_CUDA_all_Daint_extrapol.Bu3nZz0B.png",l="/ImplicitGlobalGrid.jl/previews/PR131/assets/implicit_global_grid.ZeOWNvLn.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ImplicitGlobalGrid.jl","text":"Distributed parallelization of stencil-based GPU and CPU applications","tagline":"Close to ideal weak scaling on thousands of GPUs, with as little as three functions.","actions":[{"theme":"brand","text":"Usage","link":"/usage"},{"theme":"alt","text":"API reference","link":"/api"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/eth-cscs/ImplicitGlobalGrid.jl"}],"image":{"src":"/logo.png","alt":"ImplicitGlobalGrid.jl"}}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function s(c,e,p,h,u,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="What-is-ImplicitGlobalGrid.jl?" tabindex="-1">What is ImplicitGlobalGrid.jl? <a class="header-anchor" href="#What-is-ImplicitGlobalGrid.jl?" aria-label="Permalink to &quot;What is ImplicitGlobalGrid.jl? {#What-is-ImplicitGlobalGrid.jl?}&quot;">​</a></h2><p>ImplicitGlobalGrid is an outcome of a collaboration of the Swiss National Supercomputing Centre, ETH Zurich (Dr. Samuel Omlin) with Stanford University and the Geocomputing Centre, University of Lausanne (Dr. Ludovic Räss and Prof. Yuri Podladchikov). It renders the distributed parallelization of stencil-based GPU and CPU applications on a regular staggered grid almost trivial and enables close to ideal weak scaling of real-world applications on thousands of GPUs [<a href="https://pretalx.com/juliacon2019/talk/LGHLC3/" target="_blank" rel="noreferrer">1</a>, <a href="https://pasc19.pasc-conference.org/program/schedule/presentation/?id=msa218&amp;sess=sess144" target="_blank" rel="noreferrer">2</a>, <a href="https://www.youtube.com/watch?v=vPsfZUqI4_0" target="_blank" rel="noreferrer">3</a>]:</p><p><img src="'+o+'" alt=""></p><p>ImplicitGlobalGrid relies on the Julia MPI wrapper (<a href="https://github.com/JuliaParallel/MPI.jl" target="_blank" rel="noreferrer">MPI.jl</a>) to perform halo updates close to hardware limit and leverages CUDA-aware or ROCm-aware MPI for GPU-applications. The communication can straightforwardly be hidden behind computation [<a href="https://pretalx.com/juliacon2019/talk/LGHLC3/" target="_blank" rel="noreferrer">1</a>, <a href="https://www.youtube.com/watch?v=vPsfZUqI4_0" target="_blank" rel="noreferrer">3</a>] (how this can be done automatically when using ParallelStencil.jl is shown in [<a href="https://www.youtube.com/watch?v=vPsfZUqI4_0" target="_blank" rel="noreferrer">3</a>]; a general approach particularly suited for CUDA C applications is explained in [<a href="https://on-demand.gputechconf.com/gtc/2019/video/_/S9368/" target="_blank" rel="noreferrer">4</a>]).</p><p>A particularity of ImplicitGlobalGrid is the automatic <em>implicit creation of the global computational grid</em> based on the number of processes the application is run with (and based on the process topology, which can be explicitly chosen by the user or automatically defined). As a consequence, the user only needs to write a code to solve his problem on one GPU/CPU (<em>local grid</em>); then, <strong>as little as three functions can be enough to transform a single GPU/CPU application into a massively scaling Multi-GPU/CPU application</strong>. See the <a href="/ImplicitGlobalGrid.jl/previews/PR131/examples/diffusion3D_multigpu_CuArrays_novis#example-50-lines">50-lines Multi-GPU example</a>. 1-D, 2-D and 3-D grids are supported. Here is a sketch of the global grid that results from running a 2-D solver with 4 processes (P1-P4) (a 2x2 process topology is created by default in this case):</p><p><img src="'+l+`" alt=""></p><h2 id="Installation" tabindex="-1">Installation <a class="header-anchor" href="#Installation" aria-label="Permalink to &quot;Installation {#Installation}&quot;">​</a></h2><p>ImplicitGlobalGrid can be installed directly with the <a href="https://docs.julialang.org/en/v1/stdlib/Pkg/" target="_blank" rel="noreferrer">Julia package manager</a> from the <a href="https://docs.julialang.org/en/v1/stdlib/REPL/" target="_blank" rel="noreferrer">Julia REPL</a>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-julia">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-julia">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> add ImplicitGlobalGrid</span></span></code></pre></div><h2 id="Dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#Dependencies" aria-label="Permalink to &quot;Dependencies {#Dependencies}&quot;">​</a></h2><p>ImplicitGlobalGrid relies on the Julia MPI wrapper (<a href="https://github.com/JuliaParallel/MPI.jl" target="_blank" rel="noreferrer">MPI.jl</a>) and <a href="https://github.com/omlins/CellArrays.jl" target="_blank" rel="noreferrer">CellArrays.jl</a>; GPU support is provided through package extensions for the Julia CUDA package (<a href="https://github.com/JuliaGPU/CUDA.jl" target="_blank" rel="noreferrer">CUDA.jl</a> [<a href="https://doi.org/10.1109/TPDS.2018.2872064" target="_blank" rel="noreferrer">5</a>, <a href="https://doi.org/10.1016/j.advengsoft.2019.02.002" target="_blank" rel="noreferrer">6</a>]) and the Julia AMDGPU package (<a href="https://github.com/JuliaGPU/AMDGPU.jl" target="_blank" rel="noreferrer">AMDGPU.jl</a>), and multi-threaded CPU halo copies through <a href="https://github.com/JuliaSIMD/Polyester.jl" target="_blank" rel="noreferrer">Polyester.jl</a>.</p><h2 id="Contributors" tabindex="-1">Contributors <a class="header-anchor" href="#Contributors" aria-label="Permalink to &quot;Contributors {#Contributors}&quot;">​</a></h2><p>The principal contributors to <a href="https://github.com/eth-cscs/ImplicitGlobalGrid.jl" target="_blank" rel="noreferrer">ImplicitGlobalGrid.jl</a> are (ordered by the significance of the relative contributions):</p><ul><li><p>Dr. Samuel Omlin (<a href="https://github.com/omlins" target="_blank" rel="noreferrer">@omlins</a>), CSCS - Swiss National Supercomputing Centre, ETH Zurich</p></li><li><p>Dr. Ludovic Räss (<a href="https://github.com/luraess" target="_blank" rel="noreferrer">@luraess</a>), Geocomputing Centre, University of Lausanne</p></li><li><p>Dr. Ivan Utkin (<a href="https://github.com/utkinis" target="_blank" rel="noreferrer">@utkinis</a>), Laboratory of Hydraulics, Hydrology, Glaciology - ETH Zurich</p></li></ul><h2 id="Questions,-comments-and-discussions" tabindex="-1">Questions, comments and discussions <a class="header-anchor" href="#Questions,-comments-and-discussions" aria-label="Permalink to &quot;Questions, comments and discussions {#Questions,-comments-and-discussions}&quot;">​</a></h2><p>To discuss technical issues, please post on Julia Discourse in the <a href="https://discourse.julialang.org/c/domain/gpu" target="_blank" rel="noreferrer">GPU topic</a> or the <a href="https://discourse.julialang.org/c/domain/parallel" target="_blank" rel="noreferrer">Julia at Scale topic</a> or in the <code>#gpu</code> or <code>#hpc</code> channels on the <a href="https://julialang.org/slack/" target="_blank" rel="noreferrer">Julia Slack</a>. To discuss numerical/domain-science issues, please post on Julia Discourse in the <a href="https://discourse.julialang.org/c/domain/numerics" target="_blank" rel="noreferrer">Numerics topic</a> or the <a href="https://discourse.julialang.org/c/domain/models" target="_blank" rel="noreferrer">Modelling &amp; Simulations topic</a> or whichever other topic fits best your issue.</p><h2 id="Your-contributions" tabindex="-1">Your contributions <a class="header-anchor" href="#Your-contributions" aria-label="Permalink to &quot;Your contributions {#Your-contributions}&quot;">​</a></h2><p>This project welcomes your contribution! Have you developed an application with ImplicitGlobalGrid that could be featured as an example? Please contribute it to share it with the world (if your application uses also ParallelStencil then contribute it as a mini-app in the corresponding repository)! Are you missing a convenience feature (like <a href="/ImplicitGlobalGrid.jl/previews/PR131/api#ImplicitGlobalGrid.gather!"><code>gather!</code></a>)? Then write it using MPI and contribute it to ImplicitGlobalGrid! Are you missing a great feature in the core of ImplicitGlobalGrid? Maybe you can contribute yourself! Please open an issue to discuss your idea for a contribution beforehand. Furthermore, note that a pull request should always address an issue in its completeness. Moreover, pull requests should blend nicely into the existing project; common sense is the primary guide in this regard (community guideline documents, e.g. <a href="https://github.com/SciML/ColPrac" target="_blank" rel="noreferrer">ColPrac</a>, can be consulted in addition for inspiration). We are looking forward to your contribution!</p><h2 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h2><p>[1] <a href="https://pretalx.com/juliacon2019/talk/LGHLC3/" target="_blank" rel="noreferrer">Räss, L., Omlin, S., &amp; Podladchikov, Y. Y. (2019). Porting a Massively Parallel Multi-GPU Application to Julia: a 3-D Nonlinear Multi-Physics Flow Solver. JuliaCon Conference, Baltimore, USA.</a></p><p>[2] <a href="https://pasc19.pasc-conference.org/program/schedule/presentation/?id=msa218&amp;sess=sess144" target="_blank" rel="noreferrer">Räss, L., Omlin, S., &amp; Podladchikov, Y. Y. (2019). A Nonlinear Multi-Physics 3-D Solver: From CUDA C + MPI to Julia. PASC19 Conference, Zurich, Switzerland.</a></p><p>[3] <a href="https://www.youtube.com/watch?v=vPsfZUqI4_0" target="_blank" rel="noreferrer">Omlin, S., Räss, L., Kwasniewski, G., Malvoisin, B., &amp; Podladchikov, Y. Y. (2020). Solving Nonlinear Multi-Physics on GPU Supercomputers with Julia. JuliaCon Conference, virtual.</a></p><p>[4] <a href="https://on-demand.gputechconf.com/gtc/2019/video/_/S9368/" target="_blank" rel="noreferrer">Räss, L., Omlin, S., &amp; Podladchikov, Y. Y. (2019). Resolving Spontaneous Nonlinear Multi-Physics Flow Localisation in 3-D: Tackling Hardware Limit. GPU Technology Conference 2019, San Jose, Silicon Valley, CA, USA.</a></p><p>[5] <a href="https://doi.org/10.1109/TPDS.2018.2872064" target="_blank" rel="noreferrer">Besard, T., Foket, C., &amp; De Sutter, B. (2018). Effective Extensible Programming: Unleashing Julia on GPUs. IEEE Transactions on Parallel and Distributed Systems, 30(4), 827-841. doi: 10.1109/TPDS.2018.2872064</a></p><p>[6] <a href="https://doi.org/10.1016/j.advengsoft.2019.02.002" target="_blank" rel="noreferrer">Besard, T., Churavy, V., Edelman, A., &amp; De Sutter B. (2019). Rapid software prototyping for heterogeneous and distributed platforms. Advances in Engineering Software, 132, 29-46. doi: 10.1016/j.advengsoft.2019.02.002</a></p>`,25)])])}const f=a(n,[["render",s]]);export{g as __pageData,f as default};
